// Typed view of assets/manifest.json (generated by workstream E).
// The client only reads public data: no value/trueValue ever appears here.

export interface SpriteRef {
  atlas: string;
  frame: string;
  w: number;
  h: number;
  anchor: [number, number];
  category?: string;
  silhouette?: string;
}

export interface SilhouetteRef {
  atlas: string;
  frame: string;
  w: number;
  h: number;
  anchor: [number, number];
}

export interface UiRef {
  atlas: string;
  frame: string;
  left?: number;
  right?: number;
  top?: number;
  bottom?: number;
}

export interface AudioRef {
  file: string;
  volume: number;
  loop: boolean;
}

export interface BackgroundRef {
  back: string;
  mid: string;
  front: string;
  parallax: number[];
}

export type AnimationRef =
  | { atlas: string; frames: string[]; fps: number; loop: boolean }
  | { image: string; frameWidth: number; frameHeight: number; frames: number; fps: number; loop: boolean };

export interface Manifest {
  version: number;
  game: {
    width: number;
    height: number;
    scale: number;
    pixelArt: boolean;
    roundPixels: boolean;
    antialias: boolean;
  };
  palette: {
    file: string;
    colours: number;
    silhouette: { fill: string; shade: string; outline: string };
  };
  font: { image: string; data: string; charWidth: number; lineHeight: number };
  atlases: Record<string, { image: string; data: string }>;
  sprites: Record<string, SpriteRef>;
  silhouettes: Record<string, SilhouetteRef>;
  ui: Record<string, UiRef>;
  animations: Record<string, AnimationRef>;
  backgrounds: Record<string, BackgroundRef>;
  overlays: Record<string, string>;
  audio: Record<string, AudioRef>;
  catalog: string;
}

// Vite serves the generated asset folder under /game-assets (see vite.config.ts)
// so the private assets/catalog.json is never part of the public build.
const BASE = import.meta.env.BASE_URL.endsWith("/")
  ? import.meta.env.BASE_URL.slice(0, -1)
  : import.meta.env.BASE_URL;

export const ASSET_BASE = `${BASE}/game-assets`;

export function assetUrl(relative: string): string {
  return `${ASSET_BASE}/${relative.replace(/^\//, "")}`;
}

export async function fetchManifest(): Promise<Manifest> {
  const res = await fetch(assetUrl("manifest.json"), { cache: "no-cache" });
  if (!res.ok) throw new Error(`No se pudo cargar el manifiesto (${res.status})`);
  return (await res.json()) as Manifest;
}
